<?php

namespace MongoDB\BSON;

use JsonSerializable;
use MongoDB\Driver\Exception\InvalidArgumentException;
use Stringable;

/**
 * <div id="class.mongodb-bson-int64" class="reference"> <h1 class="title">The MongoDB\BSON\Int64 class</h1>  <div class="partintro"><p class="verinfo">(mongodb &gt;=1.5.0)</p>  <div class="section" id="mongodb-bson-int64.intro">   <h2 class="title">简介</h2>   <p class="simpara">    BSON type for a 64-bit integer. When decoding BSON to PHP data, this class    is used when a 64-bit integer cannot be represented as a PHP integer on    32-bit platforms. These objects support overloaded    <a href="https://php.net/manual/zh/language.operators.arithmetic.php" class="link">arithmetic</a>,    <a href="https://php.net/manual/zh/language.operators.bitwise.php" class="link">bitwise</a>, and    <a href="https://php.net/manual/zh/language.operators.comparison.php" class="link">comparison</a> operators.   </p>   <p class="simpara">    When working with raw BSON data through the    <span class="classname"><a href="https://php.net/manual/zh/class.mongodb-bson-document.php" class="classname">MongoDB\BSON\Document</a></span>,    <span class="classname"><a href="https://php.net/manual/zh/class.mongodb-bson-packedarray.php" class="classname">MongoDB\BSON\PackedArray</a></span>, and    <span class="classname"><a href="https://php.net/manual/zh/class.mongodb-bson-iterator.php" class="classname">MongoDB\BSON\Iterator</a></span> classes, any 64-bit integer    will be returned as an instance of this class, regardless of platform and    whether the value can be represented as a PHP integer. This ensures that    values can be roundtripped without changing the type.   </p>   <p class="simpara">    During BSON encoding, objects of this class will convert back to a 64-bit    integer type, even when the value would fit in a 32-bit integer. This    allows explicitly storing values as 64-bit integers in BSON.   </p>  </div>  <div class="section" id="mongodb-bson-int64.synopsis">   <h2 class="title">类摘要</h2>   <div class="classsynopsis">    <span class="ooclass"><strong class="classname"></strong></span>    <div class="classsynopsisinfo">     <span class="modifier">final</span>     <span class="ooclass">      <span class="modifier">class</span> <strong class="classname">MongoDB\BSON\Int64</strong>     </span>     <span class="oointerface"><span class="modifier">implements</span>        <a href="https://php.net/manual/zh/class.mongodb-bson-type.php" class="interfacename">MongoDB\BSON\Type</a></span><span class="oointerface">,  <a href="https://php.net/manual/zh/class.jsonserializable.php" class="interfacename">JsonSerializable</a></span><span class="oointerface">,  <a href="https://php.net/manual/zh/class.stringable.php" class="interfacename">Stringable</a></span> {</div>    <div class="classsynopsisinfo classsynopsisinfo_comment">// 方法 </div>    <div class="methodsynopsis dc-description">   <span class="modifier">final</span> <span class="modifier">public</span> <span class="modifier">function</span> <span class="methodname" style="color:#CC7832"><a href="https://php.net/manual/zh/mongodb-bson-int64.construct.php" class="methodname" style="color:#CC7832">__construct</a></span>(<span class="methodparam"><span class="type" style="color:#EAB766"><span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.integer.php" class="type int" style="color:#EAB766">int</a></span>|<span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.string.php" class="type string" style="color:#EAB766">string</a></span></span> <span class="parameter" style="color:#3A95FF">\$value</span></span>)</div><div class="methodsynopsis dc-description"><span class="modifier">final</span> <span class="modifier">public</span> <span class="modifier">function</span> <span class="methodname" style="color:#CC7832"><a href="https://php.net/manual/zh/mongodb-bson-int64.jsonserialize.php" class="methodname" style="color:#CC7832">jsonSerialize</a></span>(): <span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.mixed.php" class="type mixed" style="color:#EAB766">mixed</a></span></div><div class="methodsynopsis dc-description"><span class="modifier">final</span> <span class="modifier">public</span> <span class="modifier">function</span> <span class="methodname" style="color:#CC7832"><a href="https://php.net/manual/zh/mongodb-bson-int64.tostring.php" class="methodname" style="color:#CC7832">__toString</a></span>(): <span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.string.php" class="type string" style="color:#EAB766">string</a></span></div>   }</div>  </div>  <div class="section">   <h2 class="title">更新日志</h2>   <table class="doctable informaltable">         <thead>      <tr>       <th>版本</th>       <th>说明</th>      </tr>     </thead>     <tbody class="tbody">             <tr>        <td>PECL mongodb 2.0.0</td>        <td>         <span class="simpara">          此类不再实现 <span class="interfacename"><a href="https://php.net/manual/zh/class.serializable.php" class="interfacename">Serializable</a></span> 接口。         </span>        </td>       </tr>      <tr>       <td>PECL mongodb 1.16.0</td>       <td>        The class can now be instantiated on all platforms. Added support for        overloaded arithmetic, bitwise, and comparison operators.       </td>      </tr>      <tr>       <td>PECL mongodb 1.12.0</td>       <td>        Implements <span class="interfacename"><a href="https://php.net/manual/zh/class.stringable.php" class="interfacename">Stringable</a></span> for PHP 8.0+.       </td>      </tr>     </tbody>       </table>  </div> </div> <h2>目录</h2><ul class="chunklist chunklist_reference"><li>{@link MongoDB\BSON\Int64::__construct} — Construct a new Int64</li><li>{@link MongoDB\BSON\Int64::jsonSerialize} — Returns a representation that can be converted to JSON</li><li>{@link MongoDB\BSON\Int64::__toString} — Returns the string representation of this Int64</li></ul></div>
 * 
 * BSON type for a 64-bit integer.
 *
 * @since 1.5.0
 * @link https://secure.php.net/manual/en/class.mongodb-bson-int64.php
 */
final class Int64 implements Type, JsonSerializable, Stringable
{
/**
 * <div id="mongodb-bson-int64.construct" class="refentry"> <div class="refnamediv">  <h1 class="refname">MongoDB\BSON\Int64::__construct</h1>  <p class="verinfo">(mongodb &gt;=1.5.0)</p><p class="refpurpose"><span class="refname">MongoDB\BSON\Int64::__construct</span> — <span class="dc-title">Construct a new Int64</span></p> </div> <div class="refsect1 description" id="refsect1-mongodb-bson-int64.construct-description">  <h3 class="title">说明</h3>  <div class="methodsynopsis dc-description">   <span class="modifier">final</span> <span class="modifier">public</span> <span class="modifier">function</span> <span class="methodname" style="color:#CC7832"><strong>MongoDB\BSON\Int64::__construct</strong></span>(<span class="methodparam"><span class="type" style="color:#EAB766"><span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.integer.php" class="type int" style="color:#EAB766">int</a></span>|<span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.string.php" class="type string" style="color:#EAB766">string</a></span></span> <span class="parameter" style="color:#3A95FF">\$value</span></span>)</div>  <p class="simpara">   Creates a new <span class="classname"><a href="https://php.net/manual/zh/class.mongodb-bson-int64.php" class="classname">MongoDB\BSON\Int64</a></span> instance for the   given integer value.  </p> </div> <div class="refsect1 parameters" id="refsect1-mongodb-bson-int64.construct-parameters">  <h3 class="title">参数</h3>  <dl>       <dt><span class="parameter" style="color:#3A95FF">value</span> (<span class="type" style="color:#EAB766"><span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.integer.php" class="type int" style="color:#EAB766">int</a></span>|<span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.string.php" class="type string" style="color:#EAB766">string</a></span></span>)</dt>    <dd>     <span class="simpara">      The value to assign to the <span class="classname"><strong class="classname">Int64</strong></span> instance. This      value can be provided as an <span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.integer.php" class="type int" style="color:#EAB766">int</a></span> or <span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.string.php" class="type string" style="color:#EAB766">string</a></span>, the      latter being required on 32-bit platforms to represent 64-bit values.     </span>    </dd>     </dl> </div> <div class="refsect1 changelog" id="refsect1-mongodb-bson-int64.construct-changelog">  <h3 class="title">更新日志</h3>  <table class="doctable informaltable">       <thead>     <tr>      <th>版本</th>      <th>说明</th>     </tr>    </thead>    <tbody class="tbody">     <tr>      <td>PECL mongodb 1.16.0</td>      <td>       <span class="simpara">        This method was made public to support creating Int64 instances when        working with raw BSON.       </span>      </td>     </tr>    </tbody>     </table> </div> <div class="refsect1 errors" id="refsect1-mongodb-bson-int64.construct-errors">  <h3 class="title">错误／异常</h3>  <ul class="simplelist">   <li>Throws <span class="classname"><a href="https://php.net/manual/zh/class.mongodb-driver-exception-invalidargumentexception.php" class="classname">MongoDB\Driver\Exception\InvalidArgumentException</a></span> on argument parsing errors.</li>   <li>Throws <span class="classname"><a href="https://php.net/manual/zh/class.mongodb-driver-exception-invalidargumentexception.php" class="classname">MongoDB\Driver\Exception\InvalidArgumentException</a></span> if string <span class="parameter" style="color:#3A95FF">value</span> cannot be parsed as a 64-bit integer.</li>  </ul> </div> <div class="refsect1 seealso" id="refsect1-mongodb-bson-int64.construct-seealso">  <h3 class="title">参见</h3>  <ul class="simplelist">   <li><a href="https://www.mongodb.com/docs/manual/reference/bson-types/" class="link external">»&nbsp;BSON Types</a></li>  </ul> </div></div>
 */
    final public function __construct(string|int $value) {}


    public static function __set_state(array $properties): self {}

    /**
 * <div id="mongodb-bson-int64.jsonserialize" class="refentry"> <div class="refnamediv">  <h1 class="refname">MongoDB\BSON\Int64::jsonSerialize</h1>  <p class="verinfo">(mongodb &gt;=1.5.0)</p><p class="refpurpose"><span class="refname">MongoDB\BSON\Int64::jsonSerialize</span> — <span class="dc-title">Returns a representation that can be converted to JSON</span></p> </div> <div class="refsect1 description" id="refsect1-mongodb-bson-int64.jsonserialize-description">  <h3 class="title">说明</h3>  <div class="methodsynopsis dc-description">   <span class="modifier">final</span> <span class="modifier">public</span> <span class="modifier">function</span> <span class="methodname" style="color:#CC7832"><strong>MongoDB\BSON\Int64::jsonSerialize</strong></span>(): <span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.mixed.php" class="type mixed" style="color:#EAB766">mixed</a></span></div> </div> <div class="refsect1 parameters" id="refsect1-mongodb-bson-int64.jsonserialize-parameters">  <h3 class="title">参数</h3>  <p class="simpara">此函数没有参数。</p> </div> <div class="refsect1 returnvalues" id="refsect1-mongodb-bson-int64.jsonserialize-returnvalues">  <h3 class="title">返回值</h3>  <p class="simpara">   Returns data which can be serialized by <span class="function">{@link json_encode()}</span> to   produce an extended JSON representation of the   <span class="classname"><a href="https://php.net/manual/zh/class.mongodb-bson-int64.php" class="classname">MongoDB\BSON\Int64</a></span>.  </p>  <blockquote class="note" style="border:1px gray solid"><p><strong class="note" style="border:1px gray solid">注意</strong>:    <span class="simpara">    The output is consistent with the    <span class="function">{@link MongoDB\BSON\toCanonicalExtendedJSON()}</span> function, which    uses the    <a href="https://github.com/mongodb/specifications/blob/master/source/extended-json/extended-json.md#canonical-extended-json-example" class="link external">»&nbsp;canonical</a>    extended JSON format. This differs from other BSON classes, which use the    driver-specific legacy extended JSON format    (<span class="function">{@link MongoDB\BSON\toJSON()}</span>), in order to ensure that the    64-bit integer value is correctly represented on 32-bit platforms.   </span>  </p></blockquote> </div> <div class="refsect1 errors" id="refsect1-mongodb-bson-int64.jsonserialize-errors">  <h3 class="title">错误／异常</h3>  <ul class="simplelist">   <li>Throws <span class="classname"><a href="https://php.net/manual/zh/class.mongodb-driver-exception-invalidargumentexception.php" class="classname">MongoDB\Driver\Exception\InvalidArgumentException</a></span> on argument parsing errors.</li>  </ul> </div> <div class="refsect1 seealso" id="refsect1-mongodb-bson-int64.jsonserialize-seealso">  <h3 class="title">参见</h3>  <ul class="simplelist">   <li><span class="methodname" style="color:#CC7832">{@link JsonSerializable::jsonSerialize()} - 指定需要被序列化成 JSON 的数据</span></li>   <li><span class="function">{@link json_encode()} - 对变量进行 JSON 编码</span></li>   <li><span class="function">{@link MongoDB\BSON\toCanonicalExtendedJSON()} - Returns the Canonical Extended JSON representation of a BSON value</span></li>   <li><span class="function">{@link MongoDB\BSON\toRelaxedExtendedJSON()} - Returns the Relaxed Extended JSON representation of a BSON value</span></li>   <li><a href="https://www.mongodb.com/docs/manual/reference/mongodb-extended-json/" class="link external">»&nbsp;MongoDB Extended JSON</a></li>  </ul> </div></div>
 * 
     * Returns a representation that can be converted to JSON
     * @link https://www.php.net/manual/en/mongodb-bson-int64.jsonserialize.php
     * @return mixed data which can be serialized by json_encode()
     * @throws InvalidArgumentException on argument parsing errors
     */
    final public function jsonSerialize(): mixed {}

    /**
 * <div id="mongodb-bson-int64.tostring" class="refentry"> <div class="refnamediv">  <h1 class="refname">MongoDB\BSON\Int64::__toString</h1>  <p class="verinfo">(mongodb &gt;=1.5.0)</p><p class="refpurpose"><span class="refname">MongoDB\BSON\Int64::__toString</span> — <span class="dc-title">Returns the string representation of this Int64</span></p> </div> <div class="refsect1 description" id="refsect1-mongodb-bson-int64.tostring-description">  <h3 class="title">说明</h3>  <div class="methodsynopsis dc-description">   <span class="modifier">final</span> <span class="modifier">public</span> <span class="modifier">function</span> <span class="methodname" style="color:#CC7832"><strong>MongoDB\BSON\Int64::__toString</strong></span>(): <span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.string.php" class="type string" style="color:#EAB766">string</a></span></div> </div> <div class="refsect1 parameters" id="refsect1-mongodb-bson-int64.tostring-parameters">  <h3 class="title">参数</h3>  <p class="simpara">此函数没有参数。</p> </div> <div class="refsect1 returnvalues" id="refsect1-mongodb-bson-int64.tostring-returnvalues">  <h3 class="title">返回值</h3>  <p class="simpara">   Returns the string representation of this Int64.  </p> </div> <div class="refsect1 examples" id="refsect1-mongodb-bson-int64.tostring-examples">  <h3 class="title">示例</h3>  <div class="example" id="example-1">   <p><strong>示例 #1 <span class="function"><strong style="color:#CC7832">MongoDB\BSON\Int64::__toString()</strong></span> example</strong></p>   <div class="example-contents"><div class="phpcode" style="border-color:gray;background:#1E1F22;"><blockquote style="border:1px gray solid;white-space:pre-wrap"><span style="color: #000000"><span style="color: #9876AA">&lt;?php<br><br>\$int64 </span><span style="color: #007700">= new </span><span style="color: #9876AA">MongoDB\BSON\Int64</span><span style="color: #007700">(</span><span style="color: #DD0000">'9223372036854775807'</span><span style="color: #007700">);<br><br></span><span style="color: #9876AA">var_dump</span><span style="color: #007700">((string) </span><span style="color: #9876AA">\$int64</span><span style="color: #007700">);<br><br></span><span style="color: #9876AA">?&gt;</span></span></blockquote></div>   </div>   <div class="example-contents"><p>以上示例的输出类似于：</p></div>   <div class="example-contents screen" style="border-color:gray;background:#1E1F22;"><div class="examplescode"><blockquote style="border:1px gray solid;">string(19)&nbsp;"9223372036854775807"</blockquote></div>   </div>  </div> </div> <div class="refsect1 seealso" id="refsect1-mongodb-bson-int64.tostring-seealso">  <h3 class="title">参见</h3>  <ul class="simplelist">   <li><a href="https://www.mongodb.com/docs/manual/reference/bson-types/" class="link external">»&nbsp;BSON Types</a></li>  </ul> </div></div>
 * 
     * Returns the Symbol as a string
     * @return string Returns the string representation of this Symbol.
     */
    final public function __toString(): string {}
}
